def get_ticket_summary() -> str:
    warehouse_id = next(w.warehouses.list()).id
    resp = w.statement_execution.execute_statement(
        statement="SELECT status, COUNT(*) AS ticket_count FROM workspace.default.tickets GROUP BY status ORDER BY ticket_count DESC",
        warehouse_id=warehouse_id,
        wait_timeout="30s",
    )
    if resp.status and resp.status.state.value == "FAILED":
        message = resp.status.error.message if resp.status.error else "unknown error"
        return f"Could not query tickets: {message}"
    rows = resp.result.data_array if resp.result else []
    if not rows:
        return "No tickets found."
    return chr(10).join(f"{status}: {count} tickets" for status, count in rows)

def get_project_tickets(project_name: str) -> str:
    from databricks.sdk.service.sql import StatementParameterListItem
    warehouse_id = next(w.warehouses.list()).id
    resp = w.statement_execution.execute_statement(
        statement="SELECT status, COUNT(*) AS ticket_count FROM workspace.default.tickets WHERE project_name = :project_name GROUP BY status ORDER BY ticket_count DESC",
        warehouse_id=warehouse_id,
        parameters=[StatementParameterListItem(name="project_name", value=project_name)],
        wait_timeout="30s",
    )
    if resp.status and resp.status.state.value == "FAILED":
        message = resp.status.error.message if resp.status.error else "unknown error"
        return f"Could not query project: {message}"
    rows = resp.result.data_array if resp.result else []
    if not rows:
        return f"No tickets found for project '{project_name}'."
    return chr(10).join(f"{status}: {count} tickets" for status, count in rows)
